import {
  Group,
  Mesh,
  PlaneGeometry,
  OctahedronGeometry,
  CylinderGeometry,
  DirectionalLight,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  Color
} from 'three/webgpu';
import {
  vec3,
  vec4,
  uv,
  mix,
  smoothstep,
  uniform
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();

  // Keep track of animations to clean up
  const timelines = [];
  const primitiveInstances = [];

  // --- PALETTE & STAGE SETUP ---
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    background: "#0b0b10",
    surface: "#101017",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [
      { at: 0, hex: "#0b0b10" },
      { at: 0.6, hex: "#12121a" },
      { at: 1, hex: "#16161d" }
    ]
  };

  // Stage vertical backdrop (gradient mesh)
  const backdropGeo = new PlaneGeometry(12, 10);
  const backdropMat = new MeshBasicNodeMaterial();
  const vUv = uv();
  const stop0 = vec3(new Color(colors.gradientStops[0].hex));
  const stop1 = vec3(new Color(colors.gradientStops[1].hex));
  const stop2 = vec3(new Color(colors.gradientStops[2].hex));
  const mixedColor = mix(stop0, mix(stop1, stop2, smoothstep(0.0, 1.0, vUv.y)), smoothstep(0.05, 0.95, vUv.y));
  backdropMat.colorNode = vec4(mixedColor, 1.0);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3.5;
  group.add(backdrop);

  // --- LOCAL LIGHTING ---
  // Ambient fill is assumed on-scene, adding local key and rim lights as requested.
  // Back rim light: strong cool directional from behind-left so long prism edges pop
  const rimLight = new DirectionalLight(0xb2d0ff, 1.4);
  rimLight.position.set(-4, 3, -3);
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  // Extra soft fill from top-right to catch PBR facets
  const fillLight = new DirectionalLight(new Color(colors.paper), 0.5);
  fillLight.position.set(3, 3, 2);
  group.add(fillLight);

  // --- CONTROLLER GROUP FOR HOVER ANIMATION ---
  const prismCluster = new Group();
  // Apply initial static rotation from spec: 12deg on z, 20deg on y
  prismCluster.rotation.z = 12 * (Math.PI / 180);
  prismCluster.rotation.y = 20 * (Math.PI / 180);
  group.add(prismCluster);

  // --- PRISM FORM CONSTRUCTION ---
  // Triangular prism: equilateral cross-section 1.2 units per side, length 1.8 units, horizontal axis.
  // An equilateral triangle inscribed in a circle of radius R. Edge length s = R * sqrt(3).
  // Given s = 1.2, R = 1.2 / sqrt(3) ~ 0.69282.
  const radius = 1.2 / Math.sqrt(3);
  const length = 1.8;
  const prismGeo = new CylinderGeometry(radius, radius, length, 3, 1, false);
  // Re-orient cylinder geometry so it lies horizontally along X axis
  prismGeo.rotateZ(Math.PI / 2);

  // Custom dispersive-look using Physical Node Material properties
  const prismMat = new MeshPhysicalNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 1.0,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color(colors.paper),
    attenuationDistance: 2.5,
    // Spec: Iridescence 1.0, iridescenceIOR 1.3, iridescenceThicknessRange [120, 480]nm
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    metalness: 0.0
  });
  // Iridescence thickness requires thinFilmThicknessRange setting
  prismMat.iridescenceThicknessRange = [120, 480];

  const prismMesh = new Mesh(prismGeo, prismMat);
  prismCluster.add(prismMesh);

  // --- EMISSIVE CORE ---
  // Core: 0.35-unit octahedron inside the prism, color #ff2a38, emissive intensity 2.2
  const coreGeo = new OctahedronGeometry(0.35);
  const coreMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 2.2,
    roughness: 0.2,
    metalness: 0.1
  });
  const coreMesh = new Mesh(coreGeo, coreMat);
  prismCluster.add(coreMesh);

  // --- Floor Caustic STREAK ---
  // 2.4 x 0.5-unit plane at y = -1.1
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  causticGeo.rotateX(-Math.PI / 2); // Lay flat on floor

  const causticMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  // Spec: engineered linear gradient of dispersed stops (#ff2a38 at 0.2, #e8ecf2 at 0.5, #9fb0c4 at 0.8)
  const cUv = uv();
  const cStop0 = vec3(new Color(colors.accent));      // #ff2a38
  const cStop1 = vec3(new Color(colors.paper));       // #e8ecf2
  const cStop2 = vec3(new Color(0x9fb0c4));           // #9fb0c4

  // Custom blend node logic
  const leftRange = smoothstep(0.2, 0.5, cUv.x);
  const rightRange = smoothstep(0.5, 0.8, cUv.x);
  const colLeft = mix(cStop0, cStop1, leftRange);
  const colGradient = mix(colLeft, cStop2, rightRange);

  // Fade bounds gracefully at the far edges of the plane
  const alphaEdge = smoothstep(0.0, 0.15, cUv.x).mul(smoothstep(1.0, 0.85, cUv.x))
    .mul(smoothstep(0.0, 0.2, cUv.y).mul(smoothstep(1.0, 0.8, cUv.y)));

  causticMat.colorNode = vec4(colGradient, alphaEdge);

  const causticMesh = new Mesh(causticGeo, causticMat);
  causticMesh.position.y = -1.1;
  causticMesh.position.z = 0.5; // Slight offset forward to align with refraction trace projection
  group.add(causticMesh);

  // --- TEXT INTERFACE & LAYOUT ---
  const textGroup = new Group();
  textGroup.position.set(0, -1.75, 0.1); // Baseline at -1.75
  group.add(textGroup);

  // Extract raw text specs safely
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineObj = items.find(v => v.role === 'headline') || { text: 'Light, machined.' };
  const captionObj = items.find(v => v.role === 'caption') || { text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION' };

  // Create headline
  const headlineMesh = ctx.fontAtlas.createText(headlineObj.text, {
    fontSize: 0.34, // Translated display scale
    color: colors.paper,
    align: 'center'
  });
  textGroup.add(headlineMesh);

  // Create caption: 0.5 units below headline, high spacing mono style
  const captionMesh = ctx.fontAtlas.createText(captionObj.text, {
    fontSize: 0.09, // Translated mono tag scale
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  captionMesh.position.y = -0.42;
  textGroup.add(captionMesh);

  // --- MOTION & INTERACTIVE BEHAVIORS ---
  // Hover & Release custom state transitions (prism tilt / stretch)
  let activeTimeline = null;

  const handlePointerMove = (e) => {
    // Normalise cursor coords [-1, 1]
    const rect = ctx.renderer.domElement.getBoundingClientRect();
    const nx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    const ny = -((e.clientY - rect.top) / rect.height) * 2 + 1;

    if (activeTimeline) activeTimeline.kill();

    // Spec: 10deg max tilt toward cursor over 350ms cubic-bezier(0.215, 0.61, 0.355, 1)
    const targetY = 20 * (Math.PI / 180) + nx * (10 * Math.PI / 180);
    const targetZ = 12 * (Math.PI / 180) + ny * (10 * Math.PI / 180);

    activeTimeline = gsap.timeline();
    activeTimeline.to(prismCluster.rotation, {
      y: targetY,
      z: targetZ,
      duration: 0.35,
      ease: "power1.out"
    });

    // Caustic stretch reaction: elongating 8 percent when the prism tilts
    activeTimeline.to(causticMesh.scale, {
      x: 1.08,
      duration: 0.35,
      ease: "power1.out"
    }, 0);
  };

  const handlePointerLeave = () => {
    if (activeTimeline) activeTimeline.kill();

    // Spec: release weighted-settle 1.04 to 1.0 over 900ms cubic-bezier(0.165, 0.84, 0.44, 1)
    activeTimeline = gsap.timeline();

    // Bounce effect / settle sequence
    activeTimeline.to(prismCluster.rotation, {
      y: 20 * (Math.PI / 180),
      z: 12 * (Math.PI / 180),
      duration: 0.9,
      ease: "elastic.out(1.04, 0.55)"
    });

    activeTimeline.to(causticMesh.scale, {
      x: 1.0,
      duration: 0.9,
      ease: "elastic.out(1.04, 0.55)"
    }, 0);
  };

  // Attach event handlers safely to returned target's userData
  group.userData.handlers = {
    pointermove: handlePointerMove,
    pointerleave: handlePointerLeave
  };

  // --- APPLY CINEMATIC PRIMITIVES ---
  const primConfig = config.cinematicPrimitives ?? [];
  for (const prim of primConfig) {
    if (ctx.primitives[prim.name]) {
      const inst = ctx.primitives[prim.name](prismCluster, prim.params);
      if (inst) {
        primitiveInstances.push(inst);
        if (inst.timeline) timelines.push(inst.timeline);
      }
    }
  }

  // --- CLEANUP ---
  group.userData.cleanup = function() {
    if (activeTimeline) activeTimeline.kill();
    timelines.forEach((tl) => tl.kill());
    primitiveInstances.forEach((inst) => {
      if (typeof inst.cleanup === 'function') inst.cleanup();
    });
    // Explicit NodeMaterial & Geometry Disposals
    backdropGeo.dispose();
    backdropMat.dispose();
    prismGeo.dispose();
    prismMat.dispose();
    coreGeo.dispose();
    coreMat.dispose();
    causticGeo.dispose();
    causticMat.dispose();
  };

  return group;
}
